WITH filtered AS (SELECT *, CASE WHEN quantity >= 198 THEN 'High' WHEN quantity >= 38 THEN 'Medium' ELSE 'Low' END AS quantity_tier FROM inventory WHERE last_restock >= TO_DATE('2023-07-23') AND quantity BETWEEN 118 AND 129), latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY product_id, store_id ORDER BY quantity) AS latest_rank FROM filtered) t WHERE latest_rank = 1), valid AS (SELECT id, store_id, product_id, quantity, last_restock, quantity_tier, latest_rank, ROUND(latest_rank, 1) AS latest_rank_rounded FROM latest WHERE latest_rank < 1), metrics AS (SELECT *, AVG(latest_rank_rounded) OVER (PARTITION BY store_id ORDER BY latest_rank, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS latest_rank_rounded_avg_6, AVG(latest_rank_rounded) OVER (ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS latest_rank_rounded_avg_6_prior, FIRST_VALUE(latest_rank_rounded, TRUE) OVER (PARTITION BY product_id ORDER BY latest_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_latest_rank_rounded, SUM(latest_rank_rounded) OVER (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_latest_rank_rounded, LAG(quantity, 1) OVER (ORDER BY latest_rank, id) AS prev_quantity FROM valid), metrics_inventory AS (SELECT id, store_id, product_id, quantity, last_restock, latest_rank, latest_rank_rounded, latest_rank_rounded_avg_6, latest_rank_rounded_avg_6_prior, first_known_latest_rank_rounded, cumulative_latest_rank_rounded, SUM(latest_rank_rounded_avg_6) OVER (ORDER BY latest_rank_rounded_avg_6, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_latest_rank_rounded_avg_6, SUM(first_known_latest_rank_rounded) OVER (PARTITION BY YEAR(last_restock), product_id ORDER BY latest_rank_rounded_avg_6_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_first_known_latest_rank_rounded FROM metrics WHERE last_restock > '2025-10-26'), enriched AS (SELECT s.*, p.sqft FROM metrics_inventory s INNER JOIN stores p ON s.store_id = p.id), deduped AS (SELECT *, RANK() OVER (PARTITION BY store_id, product_id ORDER BY latest_rank) AS dedup_rank FROM enriched QUALIFY dedup_rank = 1) SELECT id, store_id, latest_rank, latest_rank_rounded_avg_6_prior, first_known_latest_rank_rounded, running_first_known_latest_rank_rounded, sqft, dedup_rank, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY latest_rank_rounded_avg_6 DESC, id) AS event_seq, MIN(first_known_latest_rank_rounded) OVER (PARTITION BY DATE_TRUNC('YEAR', last_restock), store_id) AS last_restock_period_min_first_known_latest_rank_rounded, AVG(running_first_known_latest_rank_rounded) OVER (PARTITION BY product_id ORDER BY latest_rank_rounded_avg_6_prior, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS running_first_known_latest_rank_rounded_avg_2_prior, LAST_VALUE(quantity, TRUE) OVER (PARTITION BY store_id ORDER BY latest_rank_rounded_avg_6, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity FROM deduped
